/* Mount tooltip card */
.aa-mount {
  display: flow-root; /* keeps the card clear of floated images so it takes its own space */
  position: relative;
  box-sizing: border-box;
  width: 300px;
  max-width: 100%;
  padding: 10px 12px;
  background: linear-gradient(to bottom, rgba(24, 28, 38, 0.97), rgba(10, 12, 18, 0.97));
  border: 1px solid #5a5040;
  border-radius: 3px;
  box-shadow: 0 0 0 1px #000, 0 4px 12px rgba(0, 0, 0, 0.6);
  margin: 0 0 0.5em 0; /* small gap so cards stack nicely */
  color: #d8d2c4;
  font-size: 13px;
  line-height: 1.5;
  text-align: left;
}

/* Optional position (float parameter of Template:Mount) */
.aa-mount-right {
  float: right;
  clear: right;
  margin: 0 0 0.5em 1em;
}
.aa-mount-left {
  float: left;
  clear: left;
  margin: 0 1em 0.5em 0;
}
.aa-mount-center {
  margin: 0 auto 0.5em auto;
}

/* Header: icon, category, grade, name */
.aa-mount-head {
  display: flex;
  gap: 10px;
  align-items: center;
  margin-bottom: 6px;
}
.aa-mount-icon {
  line-height: 0;
}
.aa-mount-title {
  display: flex;
  flex-direction: column;
  line-height: 1.3;
}
.aa-mount-cat {
  color: #e8e4d8;
}
/* "Mount" is a link to the Mounts page but keeps the card's text colour */
.aa-mount-cat a,
.aa-mount-cat a:visited,
.aa-mount-cat a.new {
  color: #e8e4d8;
}
.aa-mount-cat a:hover {
  color: #ffffff;
  text-decoration: underline;
}
.aa-mount-grade {
  font-size: 13px;
}
.aa-mount-name {
  font-size: 16px;
  font-weight: bold;
}

/* Plain lines */
.aa-mount-line {
  color: #e8e4d8;
}
.aa-mount-sep {
  height: 1px;
  margin: 6px 0;
  background: linear-gradient(to right, transparent, #6a5d48, transparent);
}
.aa-mount-desc {
  color: #e8e4d8;
}

/* Skill lines */
.aa-mount-skill {
  color: #e8e4d8;
}
.aa-mount-lv {
  color: #f0563c;
}
.aa-mount-or {
  color: #e8e4d8;
}

/* A skill name you can hover over */
.aa-mskill {
  position: relative;
  display: inline-block;
  color: #7fd0f5;
  cursor: help;
  border-bottom: 1px dotted rgba(127, 208, 245, 0.55);
  outline: none;
}
.aa-mskill:hover,
.aa-mskill:focus {
  color: #b5e6ff;
  border-bottom-color: #b5e6ff;
}
.aa-mskill-tip {
  display: none;
  position: absolute;
  left: 0;
  top: 100%;
  z-index: 1000;
  box-sizing: border-box;
  width: 270px;
  margin-top: 4px;
  padding: 7px 9px;
  background: linear-gradient(to bottom, rgba(24, 28, 38, 0.98), rgba(10, 12, 18, 0.98));
  border: 1px solid #5a5040;
  border-radius: 3px;
  box-shadow: 0 0 0 1px #000, 0 4px 12px rgba(0, 0, 0, 0.6);
  color: #d8d2c4;
  font-size: 12px;
  line-height: 1.45;
  text-align: left;
  white-space: normal;
  pointer-events: none;
}
/* A card floated to the right opens its skill boxes towards the left, so they stay on the screen */
.aa-mount-right .aa-mskill-tip {
  left: auto;
  right: 0;
}
.aa-mskill:hover .aa-mskill-tip,
.aa-mskill:focus .aa-mskill-tip {
  display: block;
}
.aa-mskill-head {
  display: flex;
  gap: 8px;
  align-items: center;
  margin-bottom: 6px;
}
.aa-mskill-icon {
  display: block;
  line-height: 0;
}
.aa-mskill-icon img {
  display: block;
  width: 40px;
  height: 40px;
  border: 1px solid #000;
}
.aa-mskill-name {
  display: block;
  color: #ffffff;
  font-size: 14px;
  font-weight: bold;
}
.aa-mskill-meta {
  display: block;
  margin-bottom: 6px;
  padding: 5px 0;
  border-top: 1px solid rgba(106, 93, 72, 0.6);
  border-bottom: 1px solid rgba(106, 93, 72, 0.6);
}
.aa-mskill-metaline {
  display: block;
  color: #e8e4d8;
}
.aa-mskill-effect {
  display: block;
}
.aa-mskill-num {
  color: #fba23d;
}
.aa-mskill-none {
  display: block;
  color: #8a8478;
  font-style: italic;
}

/* Use, speed, sell */
.aa-mount-use {
  margin-top: 8px;
  color: #8a8478;
}
.aa-mount-usetext {
  color: #9acd32;
}
.aa-mount-speed {
  margin-top: 8px;
  color: #a8a396;
}
.aa-mount-speedval {
  color: #fba23d; /* the orange used in-game for the speed value */
}
.aa-mount-nosell {
  margin-top: 8px;
  color: #d9423a;
}

/* Phones and narrow windows: no floating next to the text, the card gets its own line */
@media (max-width: 500px) {
  .aa-mount.aa-mount-right,
  .aa-mount.aa-mount-left {
    float: none;
    clear: both;
    margin: 0 0 0.5em 0;
  }
  /* skill hover boxes become a panel at the bottom of the screen (tap a skill to open, tap elsewhere to close) */
  .aa-mount .aa-mskill-tip {
    position: fixed;
    left: 0.5em;
    right: 0.5em;
    top: auto;
    bottom: 0.5em;
    width: auto;
    max-height: 60vh;
    overflow-y: auto;
    margin-top: 0;
  }
}
